import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/corelib-actions.md","filePath":"modules/storage/corelib-actions.md","lastUpdated":null}'),s={name:"modules/storage/corelib-actions.md"};function i(l,t,c,n,r,h){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to &quot;CoreLib 动作&quot;">​</a></h1><p>EmakiStorage 启用后会向 CoreLib 动作注册表追加 5 个仓库段。它们可用于其他模块的奖励、触发器或管道模板中，用来存取物品、授予槽位或调整单槽上限。</p><blockquote><p>本页只记录 EmakiStorage 注册的段；CoreLib 自带通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。旧的连字符写法 <code>storage-deposit</code> 现在写作 <code>storage_deposit</code>，其余同理。</p></blockquote><p>五个段的分类都是 <code>storage</code>，目标要求都是 <code>REQUIRED_ENTITY</code>，非玩家目标会跳过。「作用于谁」由 source 决定，没有 <code>target</code> 参数：作用于执行者自己写 <code>self</code>，指定玩家用 <code>player_by_name</code>。</p><h2 id="段总览" tabindex="-1">段总览 <a class="header-anchor" href="#段总览" aria-label="Permalink to &quot;段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段 ID</th><th>说明</th></tr></thead><tbody><tr><td><code>storage_deposit</code></td><td>把物品存入目标玩家的仓库。</td></tr><tr><td><code>storage_withdraw</code></td><td>从目标玩家的仓库取出物品。</td></tr><tr><td><code>storage_grant_slot</code></td><td>增加或回收授予槽位。</td></tr><tr><td><code>storage_unlock_slot</code></td><td>不收费地增加已购买槽位。</td></tr><tr><td><code>storage_set_stacklimit</code></td><td>设置玩家级或条目级单槽上限。</td></tr></tbody></table><p>五个段都要求该玩家的仓库数据已载入内存；未载入时以 <code>MISSING_CONTEXT</code> 失败。</p><p><code>item</code> 参数是 ItemSource token，不是管道物品。这个模块按定义寻址库存商品，而不是按管道当时携带的那一叠物品，所以它不读 <code>CoreActionKeys.ITEM</code>。</p><h2 id="storage-deposit" tabindex="-1">storage_deposit <a class="header-anchor" href="#storage-deposit" aria-label="Permalink to &quot;storage_deposit&quot;">​</a></h2><p>把物品存入仓库，不触碰任何背包。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>item</code></td><td>STRING</td><td>是</td><td>—</td><td>CoreLib ItemSource token。</td></tr><tr><td><code>amount</code></td><td>INTEGER</td><td>否</td><td><code>1</code></td><td>存入数量，必须为正。</td></tr></tbody></table><p>成功时输出 <code>stored</code>，也就是实际存入的数量，可能小于请求量（部分存入）。</p><p>失败场景：</p><ul><li>仓库数据或相关服务未就绪（<code>MISSING_CONTEXT</code>）。</li><li><code>item</code> 无法解析为 ItemSource（<code>INVALID_CONFIG</code>）。</li><li><code>amount</code> 非正（<code>INVALID_CONFIG</code>）。</li><li>事务被拒绝（<code>REJECTED</code>），结果里带上 <code>reason</code>。常见原因：<code>filtered</code>（被存入过滤器拒绝）、<code>unique_rejected</code>（唯一标记物品且 <code>allow_unique_items: false</code>）、<code>no_free_slot</code>（需要新建条目但槽位已满）、<code>slot_full</code>（已达单槽上限）。</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_deposit item=diamond amount=64&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | storage_deposit item=emakiitem-forge_token amount=1&#39;</span></span></code></pre></div><h2 id="storage-withdraw" tabindex="-1">storage_withdraw <a class="header-anchor" href="#storage-withdraw" aria-label="Permalink to &quot;storage_withdraw&quot;">​</a></h2><p>从仓库取出物品并交给玩家。条目按全量 <code>ItemStack#equals</code> 定位。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>item</code></td><td>STRING</td><td>是</td><td>—</td><td>CoreLib ItemSource token。</td></tr><tr><td><code>amount</code></td><td>INTEGER</td><td>否</td><td><code>1</code></td><td>取出数量，必须为正。</td></tr></tbody></table><p>成功时输出 <code>withdrawn</code>，也就是实际取出的数量。</p><p>失败场景：</p><ul><li>仓库数据或事务服务未就绪（<code>MISSING_CONTEXT</code>）。</li><li><code>item</code> 无法解析（<code>INVALID_CONFIG</code>）。</li><li><code>amount</code> 非正（<code>INVALID_CONFIG</code>）。</li><li>事务被拒绝（<code>REJECTED</code>），结果里带上 <code>reason</code>。常见原因：<code>entry_missing</code>（仓库中没有该条目）、<code>inventory_full</code>（背包装不下且 <code>overflow_on_withdraw: return</code> 已把剩余回补仓库）。</li></ul><p>取出顺序是先扣仓库再交付。反过来会出现「交付成功、扣减失败」的复制漏洞；按此顺序最坏情况只是玩家拿到的比请求的少，而这部分剩余会立即回补。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_withdraw item=diamond amount=16&#39;</span></span></code></pre></div><h2 id="storage-grant-slot" tabindex="-1">storage_grant_slot <a class="header-anchor" href="#storage-grant-slot" aria-label="Permalink to &quot;storage_grant_slot&quot;">​</a></h2><p>调整授予槽位池，用于等级、图鉴等奖励流程。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>amount</code></td><td>INTEGER</td><td>是</td><td>—</td><td>授予槽位数。负值表示回收。</td></tr></tbody></table><p>成功时输出 <code>granted_slots</code>，也就是调整后的授予槽位总数。<code>amount</code> 为 <code>0</code> 时以 <code>INVALID_CONFIG</code> 失败。</p><p>该段记录为 <code>ADMIN_GIVE</code> 类型流水，属于强制记录，不受 <code>logging.enabled</code> 与 <code>logging.sources</code> 影响。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_grant_slot amount=10&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;player_by_name name=Steve | storage_grant_slot amount=-5&#39;</span></span></code></pre></div><h2 id="storage-unlock-slot" tabindex="-1">storage_unlock_slot <a class="header-anchor" href="#storage-unlock-slot" aria-label="Permalink to &quot;storage_unlock_slot&quot;">​</a></h2><p>不收费地增加已购买槽位，用于奖励流程。与 <code>storage_grant_slot</code> 的差别是它增加的是 <code>purchasedSlots</code> 池，会影响后续付费扩容的逐格计价起点。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>amount</code></td><td>INTEGER</td><td>是</td><td>—</td><td>解锁槽位数，必须为正。</td></tr></tbody></table><p>成功时输出 <code>purchased_slots</code>。<code>amount</code> 非正时以 <code>INVALID_CONFIG</code> 失败。</p><p>该段记录为 <code>UNLOCK</code> 类型流水，备注为 <code>cost=none</code>。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_unlock_slot amount=5&#39;</span></span></code></pre></div><h2 id="storage-set-stacklimit" tabindex="-1">storage_set_stacklimit <a class="header-anchor" href="#storage-set-stacklimit" aria-label="Permalink to &quot;storage_set_stacklimit&quot;">​</a></h2><p>设置玩家级或条目级单槽上限。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>limit</code></td><td>INTEGER</td><td>是</td><td>—</td><td>新上限，必须 <code>&gt;= 0</code>。<code>0</code> 表示继承上一级。</td></tr><tr><td><code>slot</code></td><td>INTEGER</td><td>否</td><td><code>-1</code></td><td>逻辑槽位索引。<code>-1</code>（或任何负值）表示设置玩家级默认值。</td></tr></tbody></table><p>返回数据键：</p><table tabindex="0"><thead><tr><th>场景</th><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>slot</code> 为负</td><td><code>default_stack_limit</code></td><td>设置后的玩家级上限。</td></tr><tr><td><code>slot</code> 为非负</td><td><code>slot</code></td><td>被修改的槽位索引。</td></tr><tr><td><code>slot</code> 为非负</td><td><code>stack_limit</code></td><td>设置后的条目级上限。</td></tr></tbody></table><p>失败场景：</p><ul><li>仓库数据未载入（<code>MISSING_CONTEXT</code>）。</li><li><code>limit</code> 为负（<code>INVALID_CONFIG</code>）。</li><li><code>slot</code> 为非负但该槽位没有条目（<code>INVALID_CONFIG</code>，结果里带上 <code>slot</code>）。</li></ul><p><code>0</code> 在不同层级语义不同：条目级与玩家级的 <code>0</code> 表示继承上一级，配置级 <code>capacity.default_stack_limit</code> 的 <code>0</code> 表示不限制。三级继承规则见 <a href="./configuration.html">配置详解</a>。</p><p>该段记录为 <code>ADMIN_SET</code> 类型流水，属于强制记录。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_set_stacklimit limit=100000&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_set_stacklimit limit=5000 slot=3&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | storage_set_stacklimit limit=0&#39;</span></span></code></pre></div><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./configuration.html">配置详解</a>：<code>stackLimit</code> 三级继承、存入过滤器、逐格计价。</li><li><a href="./api.html">API 与集成</a>：同样能力的代码集成入口与 <code>StorageResult</code> 状态。</li></ul>`,47)])])}const g=e(s,[["render",i]]);export{k as __pageData,g as default};
